// Canvas scenarios for ENG-2490: T1 drag preview, T2.3 canvas modal, T5 node shape, T6 indicator,
// T7 relationUtils, T8 binding, T9 view open, T10 plugin reload.
import { openCanvas, dropNode, shapes, centerOf, readState, writeState, NT, fm, sleep, consoleTrap, consoleRelease, grabEditor, collapse } from "./canvaslib.mjs";
import { mouse, move, click, dblclick, key } from "./lib.mjs";

const PANEL = ".tlui-style-panel__wrapper";
const DRAG = `${PANEL} > div:nth-child(2)`;
const raf2 = `await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));`;

const dragStyle = ({ client, json }) =>
  client.evaluate(`
    const el = app.workspace.activeLeaf.view.containerEl.querySelector(${json(DRAG)});
    if (!el) return null;
    const cs = getComputedStyle(el); const r = el.getBoundingClientRect();
    return { text: el.textContent, display: cs.display, position: cs.position, pe: cs.pointerEvents,
      w: Math.round(r.width), h: Math.round(r.height), alignItems: cs.alignItems, inline: el.getAttribute("style"),
      cx: Math.round(r.left + r.width / 2), cy: Math.round(r.top + r.height / 2) };`);

const panelButton = ({ client, json }, label) =>
  client.evaluate(`
    const b = [...app.workspace.activeLeaf.view.containerEl.querySelectorAll(${json(PANEL + " button")})].find((x) => x.textContent.trim() === ${json(label)});
    if (!b) return null; const r = b.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);

const panelRect = ({ client, json }) =>
  client.evaluate(`const r = app.workspace.activeLeaf.view.containerEl.querySelector(${json(PANEL)}).getBoundingClientRect(); return { l: r.left, t: r.top, r: r.right, b: r.bottom };`);

const showPanel = async ({ client }) => {
  await client.evaluate(`window.__dgEditor.setCurrentTool("discourse-node"); return true;`);
  await client.waitFor(`return !!app.workspace.activeLeaf.view.containerEl.querySelector(".tlui-style-panel__wrapper button")`, { label: "tool panel" });
  await sleep(300);
};

const canvasPoint = ({ client }) =>
  client.evaluate(`const r = app.workspace.activeLeaf.view.containerEl.querySelector(".tl-canvas").getBoundingClientRect(); return { x: r.left + r.width * 0.35, y: r.top + r.height * 0.3 };`);

const modalTitleGeom = ({ client }) =>
  client.evaluate(`
    const t = [...document.querySelectorAll(".modal-container textarea")].find((el) => el.className.includes("bg-background-primary"));
    const p = document.querySelector(".modal-container .suggestion-container");
    const sel = document.querySelector(".modal-container select");
    const tr = t?.getBoundingClientRect(); const pr = p?.getBoundingClientRect();
    return { modal: !!document.querySelector(".modal-container"), type: sel ? sel.options[sel.selectedIndex]?.text : null,
      pop: !!p, dTop: p ? Math.round(pr.top - tr.bottom) : null, dLeft: p ? Math.round(pr.left - tr.left) : null };`);

const indicatorSig = ({ client }) =>
  client.evaluate(`return (async () => { ${raf2}
    const root = app.workspace.activeLeaf.view.containerEl;
    return [...root.querySelectorAll("g.tl-shape-indicator")].map((g) => [...g.querySelectorAll("*")].map((e) => e.tagName).join(",")); })();`);

const relMask = ({ client, json }, rel) =>
  client.evaluate(`return (async () => { ${raf2}
    const root = app.workspace.activeLeaf.view.containerEl;
    return [...root.querySelectorAll("mask")].map((m) => m.id).filter((id) => id.startsWith(${json(rel.replace(":", "_"))})); })();`);

const ensureFixture = async (ctx) => {
  const st = readState();
  if (!st.rel) throw new Error("no canvas fixture: run C0 first");
  await openCanvas(ctx);
  return st;
};

const bindings = ({ client, json }, rel) =>
  client.evaluate(`return window.__dgEditor.getBindingsFromShape(${json(rel)}, "discourse-relation").map((b) => ({ terminal: b.props.terminal, toId: b.toId }));`);

export default [
  {
    name: "C0 fixture: new canvas, 2 dropped nodes, relation tool",
    input: "create canvas; drop Evidence + Claim notes; panel 'supports'; drag Evidence → Claim",
    expected: "2 discourse-node shapes sized 160x67 with titles = basenames; 1 relation text 'supports' bound both ends (T5.1, T5.6 drop, T6.4, T8.7 tool, T9.1 create)",
    run: async (ctx) => {
      const { client } = ctx;
      const ev = await ctx.writeNote("ev-node.md", fm(NT.evidence, "evidence body"));
      const cl = await ctx.writeNote("cl-node.md", fm(NT.claim, "claim body"));
      await sleep(800);
      const st = await openCanvas(ctx, { fresh: true });
      st.ev = ev; st.cl = cl;
      const vp = await client.evaluate(`const b = window.__dgEditor.getViewportPageBounds(); return { x: b.x, y: b.y, w: b.w, h: b.h };`);
      await dropNode(ctx, ev, { x: vp.x + vp.w * 0.25, y: vp.y + vp.h * 0.55 });
      await dropNode(ctx, cl, { x: vp.x + vp.w * 0.6, y: vp.y + vp.h * 0.55 });
      await client.waitFor(`return window.__dgEditor.getCurrentPageShapes().filter((s) => s.type === "discourse-node").length >= 2`, { label: "2 nodes" });
      await sleep(1000);
      const nodes = (await shapes(ctx)).filter((s) => s.type === "discourse-node");
      await showPanel(ctx);
      await client.evaluate(`[...app.workspace.activeLeaf.view.containerEl.querySelectorAll(".tlui-style-panel__wrapper button")].find((b) => b.textContent.trim() === "supports").click(); return true;`);
      await sleep(300);
      const a = await centerOf(ctx, nodes[0].id);
      const b = await centerOf(ctx, nodes[1].id);
      await move(ctx, a.x, a.y, false);
      await mouse(ctx, "mousePressed", a.x, a.y);
      for (let i = 1; i <= 10; i++) await move(ctx, a.x + ((b.x - a.x) * i) / 10, a.y + ((b.y - a.y) * i) / 10);
      await mouse(ctx, "mouseReleased", b.x, b.y);
      await sleep(1200);
      const rel = (await shapes(ctx)).find((s) => s.type === "discourse-relation");
      Object.assign(st, { A: nodes[0].id, B: nodes[1].id, rel: rel?.id });
      writeState(st);
      await client.evaluate(`window.__dgEditor.setCurrentTool("select"); return true;`);
      return {
        nodes: nodes.map((n) => ({ title: n.props.title, w: n.props.w, h: n.props.h })),
        relText: rel?.props.text, binds: rel ? await bindings(ctx, rel.id) : [],
      };
    },
    expect: (a) => ({
      pass: a.nodes.length === 2 && a.nodes.every((n) => n.w > 0 && n.h > 0) && a.nodes.map((n) => n.title).sort().join() === "cl-node,ev-node" && a.relText === "supports" && a.binds.length === 2,
      actual: JSON.stringify(a),
    }),
  },
  {
    name: "T1.1 drag preview follows cursor, hides over panel; drop opens modal (+T2.3, T5.6)",
    input: "press Claim in panel; drag >10px onto canvas; back over panel; out again; release; pick existing node via search; Confirm",
    expected: "outside: 50x50 'Claim' box, fixed, pointer-events none, flex, centred on cursor; over panel: display none; modal Type=Claim, popover dTop 8; node created at drop with 160x67",
    run: async (ctx) => {
      const { client } = ctx;
      await ensureFixture(ctx);
      await showPanel(ctx);
      const btn = await panelButton(ctx, "Claim");
      const pr = await panelRect(ctx);
      const out = await canvasPoint(ctx);
      await move(ctx, btn.x, btn.y, false);
      await mouse(ctx, "mousePressed", btn.x, btn.y);
      for (let i = 1; i <= 8; i++) await move(ctx, btn.x + ((out.x - btn.x) * i) / 8, btn.y + ((out.y - btn.y) * i) / 8);
      await sleep(150);
      const outside = await dragStyle(ctx);
      await move(ctx, (pr.l + pr.r) / 2, pr.t + 10);
      await sleep(150);
      const overPanel = await dragStyle(ctx);
      await move(ctx, out.x, out.y);
      await sleep(150);
      const outside2 = await dragStyle(ctx);
      const before = (await shapes(ctx)).filter((s) => s.type === "discourse-node").length;
      await mouse(ctx, "mouseReleased", out.x, out.y);
      await client.waitFor(`return !!document.querySelector(".modal-container textarea")`, { label: "modal" });
      await sleep(300);
      await client.evaluate(`[...document.querySelectorAll(".modal-container textarea")].find((el) => el.className.includes("bg-background-primary")).focus(); return true;`);
      await client.typeText("cl-no");
      await client.waitFor(`return document.querySelectorAll(".modal-container .suggestion-container .suggestion-item").length > 0`, { label: "results" });
      await sleep(300);
      const modal = await modalTitleGeom(ctx);
      await client.key(key("ArrowDown", "ArrowDown", 40));
      await client.key(key("Enter", "Enter", 13));
      await sleep(400);
      await client.evaluate(`[...document.querySelectorAll(".modal-container button")].find((b) => b.textContent.trim() === "Confirm")?.click(); return true;`);
      await sleep(1500);
      const after = (await shapes(ctx)).filter((s) => s.type === "discourse-node");
      const created = after.length > before ? after[after.length - 1] : null;
      const dropPage = await client.evaluate(`const p = window.__dgEditor.screenToPage(${JSON.stringify(out)}); return { x: p.x, y: p.y };`);
      if (created) await client.evaluate(`window.__dgEditor.deleteShapes([${JSON.stringify(created.id)}]); return true;`);
      return { outside, overPanel, outside2, cursor: out, modal,
        created: created && { w: created.props.w, h: created.props.h, title: created.props.title, dx: Math.round(created.x - dropPage.x), dy: Math.round(created.y - dropPage.y) } };
    },
    expect: (a) => {
      const o = a.outside;
      const ok = o && o.text === "Claim" && o.position === "fixed" && o.pe === "none" && o.w === 50 && o.h === 50 && o.display === "flex" && o.alignItems === "center"
        && Math.abs(o.cx - a.cursor.x) <= 2 && Math.abs(o.cy - a.cursor.y) <= 2
        && a.overPanel.display === "none" && a.outside2.display === "flex"
        && a.modal.type === "Claim" && a.modal.pop && a.modal.dTop === 8 && a.modal.dLeft === 0
        && a.created && a.created.w > 0 && a.created.h > 0;
      return { pass: !!ok, actual: JSON.stringify(a) };
    },
  },
  {
    name: "T1.2 Escape mid-drag cancels",
    input: "press Claim; drag onto canvas; Escape; release",
    expected: "preview hidden/empty; no modal; no new node",
    run: async (ctx) => {
      const { client } = ctx;
      await ensureFixture(ctx);
      await showPanel(ctx);
      const btn = await panelButton(ctx, "Claim");
      const out = await canvasPoint(ctx);
      const before = (await shapes(ctx)).length;
      await move(ctx, btn.x, btn.y, false);
      await mouse(ctx, "mousePressed", btn.x, btn.y);
      for (let i = 1; i <= 8; i++) await move(ctx, btn.x + ((out.x - btn.x) * i) / 8, btn.y + ((out.y - btn.y) * i) / 8);
      await sleep(150);
      const during = await dragStyle(ctx);
      await client.pressEscape();
      await sleep(200);
      const afterEsc = await dragStyle(ctx);
      await mouse(ctx, "mouseReleased", out.x, out.y);
      await sleep(700);
      return { during, afterEsc, modal: await client.evaluate(`return !!document.querySelector(".modal-container")`), added: (await shapes(ctx)).length - before };
    },
    expect: (a) => ({ pass: a.during?.display === "flex" && (a.afterEsc.display === "none" || a.afterEsc.text === "") && !a.modal && a.added === 0, actual: JSON.stringify(a) }),
  },
  {
    name: "T1.3 click without drag focuses type; canvas click opens modal",
    input: "click Claim (no move); count panel node buttons; click canvas",
    expected: "no preview; panel shows only Claim; modal opens with Type=Claim",
    run: async (ctx) => {
      const { client } = ctx;
      await ensureFixture(ctx);
      await showPanel(ctx);
      const btn = await panelButton(ctx, "Claim");
      await click(ctx, btn.x, btn.y);
      await sleep(400);
      const preview = await dragStyle(ctx);
      const buttons = await client.evaluate(`return [...app.workspace.activeLeaf.view.containerEl.querySelectorAll(".tlui-style-panel__wrapper button[data-dg_node_type_id]")].map((b) => b.textContent.trim());`);
      const tool = await client.evaluate(`return window.__dgEditor.getCurrentToolId();`);
      const out = await canvasPoint(ctx);
      await click(ctx, out.x, out.y);
      await client.waitFor(`return !!document.querySelector(".modal-container")`, { label: "modal", timeoutMs: 4000 }).catch(() => {});
      await sleep(300);
      const modal = await modalTitleGeom(ctx);
      await client.pressEscape();
      return { preview, buttons, tool, modal };
    },
    expect: (a) => ({ pass: (a.preview?.display === "none" || !a.preview?.text) && a.buttons.join() === "Claim" && a.modal.modal && a.modal.type === "Claim", actual: JSON.stringify(a) }),
  },
  {
    name: "T5.2 rename from canvas widens node",
    input: "double-click Evidence node; replace title with a longer one; Confirm",
    expected: "file renamed; shape title updated; shape width grows",
    run: async (ctx) => {
      const { client, json } = ctx;
      const st = await ensureFixture(ctx);
      const before = (await shapes(ctx)).find((s) => s.id === st.A);
      const c = await centerOf(ctx, st.A);
      await client.evaluate(`window.__dgEditor.setCurrentTool("select"); return true;`);
      await dblclick(ctx, c.x, c.y);
      await client.waitFor(`return !!document.querySelector(".modal-container textarea")`, { label: "edit modal" });
      await sleep(300);
      await client.evaluate(`const t = [...document.querySelectorAll(".modal-container textarea")].find((el) => el.className.includes("bg-background-primary")); t.focus(); t.select(); return true;`);
      await client.typeText("ev-node with a much much longer title for width");
      await sleep(200);
      await client.evaluate(`[...document.querySelectorAll(".modal-container button")].find((b) => b.textContent.trim() === "Confirm")?.click(); return true;`);
      await sleep(2000);
      const after = (await shapes(ctx)).find((s) => s.id === st.A);
      const fileExists = await client.evaluate(`return !!app.vault.getAbstractFileByPath(${json(st.ev.replace("ev-node.md", "ev-node with a much much longer title for width.md"))});`);
      return { before: { title: before.props.title, w: before.props.w }, after: { title: after.props.title, w: after.props.w }, fileExists };
    },
    expect: (a) => ({ pass: a.fileExists && a.after.title.startsWith("ev-node with") && a.after.w > a.before.w, actual: JSON.stringify(a) }),
    teardown: async ({ client, json }) => {
      const st = readState();
