        const f = app.vault.getAbstractFileByPath(${json(st.ev.replace("ev-node.md", "ev-node with a much much longer title for width.md"))});
        if (f) await app.fileManager.renameFile(f, ${json(st.ev)}); return true; })();`);
      await sleep(800);
