    run: async (ctx) => {
      const { client, json } = ctx;
      const st = readState();
      await ctx.writeNote("ev-node.md", fm(NT.evidence, "evidence body\n\n![[Pasted image 20250226085511.png]]"));
      const setKey = (v) => client.evaluate(`return (async () => { const p = app.plugins.plugins["@discourse-graph/obsidian"];
        p.settings.nodeTypes = p.settings.nodeTypes.map((n) => n.id === ${json(NT.evidence)} ? { ...n, keyImage: ${v} } : n); await p.saveSettings(); return true; })();`);
      const read = async () => { await openCanvas(ctx); await sleep(2500); const s = (await shapes(ctx)).find((x) => x.id === st.A); return { img: !!s.props.imageSrc, h: s.props.h, w: s.props.w }; };
      const base = await read();
