import { TextFileView, TFile, WorkspaceLeaf } from "obsidian";
import { VIEW_TYPE_TLDRAW_DG_PREVIEW } from "~/constants";
import { Root, createRoot } from "react-dom/client";
import { TldrawPreviewComponent } from "./TldrawViewComponent";
import { TLStore } from "tldraw";
import React from "react";
import DiscourseGraphPlugin from "~/index";
import { processInitialData } from "~/components/canvas/utils/tldraw";
import { ObsidianTLAssetStore } from "~/components/canvas/stores/assetStore";
import { PluginProvider } from "../PluginContext";
import {
  CanvasFileState,
  parseCanvasFileState,
} from "~/components/canvas/utils/canvasFileSync";

export class TldrawView extends TextFileView {
  plugin: DiscourseGraphPlugin;
  private reactRoot?: Root;
  private store: TLStore | null = null;
  private assetStore: ObsidianTLAssetStore | null = null;
  private canvasUuid: string | null = null;
  private initialFileState: CanvasFileState | null = null;
  private onUnloadCallbacks: (() => void)[] = [];

  constructor(leaf: WorkspaceLeaf, plugin: DiscourseGraphPlugin) {
    super(leaf);
    this.plugin = plugin;
    this.navigation = true;
  }

  getViewType(): string {
    return VIEW_TYPE_TLDRAW_DG_PREVIEW;
  }

  getDisplayText(): string {
    return this.file?.basename ?? "Discourse Graph Canvas Preview";
  }

  getViewData(): string {
    return this.data;
  }

  setViewData(data: string): void {
    this.data = data;
  }

  clear(): void {
    this.data = "";
  }

  protected get tldrawContainer() {
    return this.containerEl.children[1];
  }

  override onload(): void {
    super.onload();
    this.contentEl.addClass("tldraw-view-content");
    this.addAction("file-text", "View as markdown", () =>
      this.leaf.setViewState({
        type: "markdown",
        state: this.leaf.view.getState(),
      }),
    );
  }

  // eslint-disable-next-line @typescript-eslint/require-await -- ItemView.onOpen must return a Promise; nothing to await
  async onOpen(): Promise<void> {
    const container = this.tldrawContainer;
    if (!container) return;

    container.empty();
  }

  async onLoadFile(file: TFile): Promise<void> {
    await super.onLoadFile(file);

    const fileData = await this.app.vault.read(file);

    const assetStore = new ObsidianTLAssetStore(
      `tldraw-${encodeURIComponent(file.path)}`,
      {
        app: this.app,
        file,
        plugin: this.plugin,
      },
    );
    const store = this.createStore(fileData, assetStore);

    if (!store) {
      return;
    }

    this.assetStore = assetStore;
    await this.setStore(store);
  }

  private createStore(
    fileData: string,
    assetStore: ObsidianTLAssetStore,
  ): TLStore | undefined {
    try {
      const fileState = parseCanvasFileState(fileData);
      if (!fileState) {
        return;
      }

      this.initialFileState = fileState;
      const { data } = fileState;
      if (data.meta?.uuid) {
        this.canvasUuid = data.meta.uuid;
      } else {
        this.canvasUuid = window.crypto.randomUUID();
      }

      if (!this.file) {
        return;
      }

      const { store } = processInitialData(data, assetStore, {
        app: this.app,
        canvasFile: this.file,
        plugin: this.plugin,
      });

      return store;
    } catch (e) {
      console.error("Failed to create store from file data", e);
      return;
    }
  }

  private assertInitialized(): void {
    if (!this.file) throw new Error("TldrawView not initialized: missing file");
    if (!this.assetStore)
      throw new Error("TldrawView not initialized: missing assetStore");
    if (!this.store)
      throw new Error("TldrawView not initialized: missing store");
  }

  private createReactRoot(entryPoint: Element, store: TLStore) {
    const root = createRoot(entryPoint);
    if (!this.file) throw new Error("TldrawView not initialized: missing file");
    if (!this.assetStore)
      throw new Error("TldrawView not initialized: missing assetStore");
    if (!this.store)
      throw new Error("TldrawView not initialized: missing store");
    if (!this.canvasUuid)
      throw new Error("TldrawView not initialized: missing canvas UUID");

    if (!this.assetStore) {
      return;
    }

    root.render(
      <React.StrictMode>
        <PluginProvider plugin={this.plugin}>
          <TldrawPreviewComponent
            store={store}
            file={this.file}
            assetStore={this.assetStore}
            canvasUuid={this.canvasUuid}
            initialFileState={this.initialFileState}
          />
        </PluginProvider>
      </React.StrictMode>,
    );
    return root;
  }

  protected async setStore(store: TLStore) {
    if (this.store) {
      try {
        this.store.dispose();
      } catch (e) {
        console.error("Failed to dispose old store", e);
      }
    }

    this.store = store;
    if (this.tldrawContainer) {
      await this.refreshView();
    }
  }

  private async refreshView() {
    if (!this.store) return;

    if (this.reactRoot) {
      try {
        const container = this.tldrawContainer;
        if (container?.hasChildNodes()) {
          this.reactRoot.unmount();
        }
      } catch (e) {
        console.error("Failed to unmount React root", e);
      }
      this.reactRoot = undefined;
    }

    const container = this.tldrawContainer;
    if (container) {
      this.reactRoot = this.createReactRoot(container, this.store);
      await new Promise((resolve) => setTimeout(resolve, 0)); // Wait for React to render
    }
  }

  registerOnUnloadFile(callback: () => void) {
    this.onUnloadCallbacks.push(callback);
  }

  async onUnloadFile(file: TFile): Promise<void> {
    const callbacks = [...this.onUnloadCallbacks];
    this.onUnloadCallbacks = [];
    callbacks.forEach((cb) => cb());

    if (this.assetStore) {
      this.assetStore.dispose();
      this.assetStore = null;
    }

    return super.onUnloadFile(file);
  }

  async onClose() {
    await super.onClose();

    if (this.reactRoot) {
      try {
        const container = this.tldrawContainer;
        if (container?.hasChildNodes()) {
          this.reactRoot.unmount();
        }
      } catch (e) {
        console.error("Failed to unmount React root", e);
      }
      this.reactRoot = undefined;
    }

    if (this.store) {
      try {
        this.store.dispose();
      } catch (e) {
        console.error("Failed to dispose store", e);
      }
      this.store = null;
    }

    if (this.assetStore) {
      this.assetStore.dispose();
      this.assetStore = null;
    }
  }
}

import { config } from "@repo/eslint-config/react-internal";

export default [
  ...config,
  {
    files: ["**/*.{ts,tsx,mts,cts}"],
    languageOptions: {
      parserOptions: {
        tsconfigRootDir: import.meta.dirname,
        project: true,
        ecmaFeatures: {
          jsx: true,
        },
      },
    },
  },
  {
    // Copied from tldraw's arrow code, which uses function declarations throughout.
    files: ["src/components/canvas/utils/relationUtils.tsx"],
    rules: { "preferArrows/prefer-arrow-functions": "off" },
  },
];

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

