// Screencast recorder: own CDP socket on the vault's page, frames -> mp4 with a caption.
import { mkdirSync, writeFileSync, rmSync } from "node:fs";
import { execFileSync } from "node:child_process";
import path from "node:path";
import { listTargets } from "/Users/trang.doan/.claude/skills/dg-obsidian-cdp-verify/scripts/driver.mjs";

const OUT = "/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/dad56eb0-85c8-43af-afe3-79e3dc24c31b/scratchpad/videos";
const FONT = "/System/Library/Fonts/Supplemental/Arial.ttf";

const openSocket = (url) =>
  new Promise((resolve, reject) => {
    const ws = new WebSocket(url);
    let id = 0;
    const pending = new Map();
    const handlers = [];
    ws.addEventListener("open", () =>
      resolve({
        send: (method, params = {}) =>
          new Promise((res, rej) => {
            const n = ++id;
            pending.set(n, { res, rej });
            ws.send(JSON.stringify({ id: n, method, params }));
          }),
        on: (fn) => handlers.push(fn),
        close: () => ws.close(),
      }),
    );
    ws.addEventListener("error", reject);
    ws.addEventListener("message", (e) => {
      const msg = JSON.parse(e.data.toString());
      if (msg.id && pending.has(msg.id)) {
        const p = pending.get(msg.id);
        pending.delete(msg.id);
        msg.error ? p.rej(new Error(JSON.stringify(msg.error))) : p.res(msg.result);
      } else if (msg.method) handlers.forEach((h) => h(msg));
    });
  });

const findPage = async (root, port) => {
  for (const t of await listTargets(port)) {
    const s = await openSocket(t.webSocketDebuggerUrl);
    const r = await s.send("Runtime.evaluate", {
      expression: `!!document.querySelector(".workspace") && app?.vault?.adapter?.basePath === ${JSON.stringify(root)}`,
      returnByValue: true,
    });
    if (r.result?.value === true) return s;
    s.close();
  }
  throw new Error("recorder: vault page not found");
};

// Visible cursor: CDP input moves no OS pointer, so draw one that follows DOM pointer events.
const CURSOR_ON = `(() => {
  if (document.getElementById("rec-cursor")) return;
  const c = document.createElement("div");
  c.id = "rec-cursor";
  c.style.cssText = "position:fixed;left:0;top:0;width:18px;height:18px;margin:-9px 0 0 -9px;border-radius:50%;background:rgba(255,80,80,.55);border:2px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.4);pointer-events:none;z-index:2147483647;transition:transform .08s";
  document.body.appendChild(c);
  const mv = (e) => { c.style.left = e.clientX + "px"; c.style.top = e.clientY + "px"; };
  const dn = () => { c.style.transform = "scale(.6)"; c.style.background = "rgba(255,40,40,.9)"; };
  const up = () => { c.style.transform = ""; c.style.background = "rgba(255,80,80,.55)"; };
  window.__recCursor = { mv, dn, up };
  window.addEventListener("pointermove", mv, true);
  window.addEventListener("pointerdown", dn, true);
  window.addEventListener("pointerup", up, true);
})()`;
const CURSOR_OFF = `(() => {
  const h = window.__recCursor;
  if (h) { window.removeEventListener("pointermove", h.mv, true); window.removeEventListener("pointerdown", h.dn, true); window.removeEventListener("pointerup", h.up, true); }
  document.getElementById("rec-cursor")?.remove();
})()`;

export const startRecording = async ({ root, port = 9222, slug, caption }) => {
  const dir = path.join(OUT, "frames", slug);
  rmSync(dir, { recursive: true, force: true });
  mkdirSync(dir, { recursive: true });
  const s = await findPage(root, port);
  await s.send("Runtime.evaluate", { expression: CURSOR_ON });
  const frames = [];
  s.on((msg) => {
    if (msg.method !== "Page.screencastFrame") return;
    const { data, metadata, sessionId } = msg.params;
    const file = path.join(dir, `f${String(frames.length).padStart(5, "0")}.jpg`);
    writeFileSync(file, Buffer.from(data, "base64"));
    frames.push({ file, t: metadata.timestamp });
    s.send("Page.screencastFrameAck", { sessionId }).catch(() => {});
  });
  await s.send("Page.startScreencast", { format: "jpeg", quality: 85, maxWidth: 1600, maxHeight: 1100 });
  const t0 = Date.now();
  return {
    stop: async ({ holdMs = 1500 } = {}) => {
      await new Promise((r) => setTimeout(r, holdMs));
      await s.send("Page.stopScreencast").catch(() => {});
      await s.send("Runtime.evaluate", { expression: CURSOR_OFF }).catch(() => {});
      s.close();
      if (frames.length === 0) throw new Error(`recorder: no frames for ${slug}`);
      const list = frames
        .map((f, i) => {
          const next = frames[i + 1]?.t ?? f.t + holdMs / 1000;
          return `file '${f.file}'\nduration ${Math.max(next - f.t, 0.001).toFixed(3)}`;
        })
        .join("\n") + `\nfile '${frames.at(-1).file}'\n`;
      const listFile = path.join(dir, "list.txt");
      writeFileSync(listFile, list);
      const capFile = path.join(dir, "caption.txt");
      writeFileSync(capFile, caption);
      const out = path.join(OUT, `${slug}.mp4`);
      execFileSync("ffmpeg", [
        "-y", "-loglevel", "error", "-f", "concat", "-safe", "0", "-i", listFile,
        "-vf",
        `fps=30,scale=trunc(iw/2)*2:trunc(ih/2)*2,drawtext=fontfile=${FONT}:textfile=${capFile}:x=16:y=h-th-16:fontsize=22:fontcolor=white:box=1:boxcolor=black@0.65:boxborderw=10`,
        "-c:v", "libx264", "-pix_fmt", "yuv420p", "-movflags", "+faststart", "-an", out,
      ]);
      return { out, frames: frames.length, ms: Date.now() - t0 };
    },
  };
};

// Wrap scenarios so each run() is recorded; `slow` adds a beat after run for viewers.
export const recorded = (scenarios, { prefix, captionOf = (s) => s.name } = {}) =>
  scenarios.map((sc, i) => ({
    ...sc,
    run: async (ctx, state) => {
      const slug = `${prefix}-${String(i + 1).padStart(2, "0")}-${sc.name.split(" ")[0].replace(/[^\w.-]/g, "")}`;
      const rec = await startRecording({ root: ctx.vault.root, slug, caption: captionOf(sc) });
      try {
        return await sc.run(ctx, state);
      } finally {
        const r = await rec.stop();
        console.log(`REC ${r.out} frames=${r.frames} ms=${r.ms}`);
      }
    },
  }));

