})()`;

export const startRecording = async ({ root, port = 9222, slug, caption }) => {
  const dir = path.join(OUT, "frames", slug);
  rmSync(dir, { recursive: true, force: true });
  mkdirSync(dir, { recursive: true });
  const s = await findPage(root, port);
  await s.send("Runtime.evaluate", { expression: CURSOR_ON });
  const frames = [];
  s.on((msg) => {
    if (msg.method !== "Page.screencastFrame") return;
    const { data, metadata, sessionId } = msg.params;
    const file = path.join(dir, `f${String(frames.length).padStart(5, "0")}.jpg`);
    writeFileSync(file, Buffer.from(data, "base64"));
    frames.push({ file, t: metadata.timestamp });
    s.send("Page.screencastFrameAck", { sessionId }).catch(() => {});
  });
  await s.send("Page.startScreencast", { format: "jpeg", quality: 85, maxWidth: 1600, maxHeight: 1100 });
  const t0 = Date.now();
  return {
    stop: async ({ holdMs = 1500 } = {}) => {
      await new Promise((r) => setTimeout(r, holdMs));
      await s.send("Page.stopScreencast").catch(() => {});
      await s.send("Runtime.evaluate", { expression: CURSOR_OFF }).catch(() => {});
