D=/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/dad56eb0-85c8-43af-afe3-79e3dc24c31b/scratchpad; node -e '
const fs=require("fs");const D=process.argv[1];
const m=Object.fromEntries(fs.readFileSync(D+"/videos/urls.tsv","utf8").trim().split("\n").map(l=>l.split("\t")));
let t=fs.readFileSync(D+"/videos/matrix.tmpl.md","utf8");const miss=[];
t=t.replace(/\{([A-Z][\w.\-]*)\}/g,(_,k)=>m[k]?`[▶ ${k}](${m[k]})`:(miss.push(k),_));
if(miss.length){console.error(miss);process.exit(1)}
let b=fs.readFileSync(D+"/pr-body.md","utf8");
const s=b.indexOf("<details><summary>CDP scenario matrix"), e=b.indexOf("## Scope check");
b=b.slice(0,s)+t+b.slice(e);
b=b.replace("- Hand-tested in Obsidian:", "- Hand-tested in Obsidian:");
fs.writeFileSync(D+"/pr-body.md",b);
console.log("links",(t.match(/▶/g)||[]).length,"rows",(t.match(/\| ✅ \|/g)||[]).length);
' $D; grep -n "^## " $D/pr-body.md

